"""Standalone LOSO methods and results report from saved measurements."""
from pathlib import Path
import csv,json
ROOT=Path(__file__).parent
OUT=ROOT/'reports/loso';OUT.mkdir(parents=True,exist_ok=True)
def read(p):return list(csv.DictReader((ROOT/p).open(encoding='utf-8-sig')))
comp=read('outputs/final/comparison.csv');folds=read('outputs/loso/fold_metrics.csv');bias=read('outputs/final/angle_bias.csv')
protocol=json.loads((ROOT/'outputs/loso/protocol.json').read_text())
def row(p,u,m):return next(r for r in comp if r['protocol']==p and r['unit']==u and r['model']==m)
def pct(x):return f'{float(x)*100:.2f}'
blocks=[]
def text(t,kind='body'):blocks.append((kind,t))
def table(rs,ws):blocks.append(('table',(rs,ws)))
def picture(p,w,h):blocks.append(('image',(str(ROOT/p),w,h)))
def page():blocks.append(('page',None))
